---FillPack
---@param data PhoneGiftPackUpVo @ 包装vo
function UIFeelingShopPackNode:FillPack(data)
    if not data then
        return
    end

    CfUtils.FillText(self.TxtGiftName, data.name)
    local num = PhoneUtils.GetPhonePackGradeUpNum(self._curGiftId, data.id)
    CfUtils.FillText(self.TxtNumber, "+"..num)
    if checkNumber(data.coinAmount) > 0 then
        CfUtils.FillText(self.Text, data.coinAmount)
    else
        CfUtils.FillText(self.Text, "FREE")
    end
    CfUtils.FillImage(self.icon, GoodsConfMgr:GetInstance():GetPhotoPathById(data.coinId))
    CfUtils.FillImage(self.IconGift, data.photoId)
end

